func EncodeBlob(s string) ([]byte, error) {
  cs := C.CString(s)
  defer C.free(unsafe.Pointer(cs))
  var outLen C.size_t
  var err C.int
  buf := C.encode_bin(cs, &outLen, &err)
  if err != 0 || buf == nil {
    return nil, fmt.Errorf("encode error %d", int(err))
  }
  b := C.GoBytes(unsafe.Pointer(buf), C.int(outLen))
  C.free(unsafe.Pointer(buf))
  return b, nil
}
```

